#!/bin/bash
set -e

# Invoice Modification: original line items (present when the invoice
# was opened) are now locked -- no Remove button, shown with a lock icon.
# Only items added during the current modification session can be
# removed. Patient name gets a lock icon for the same reason. The Add
# Line Item form was already there and is unchanged.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/billing/cancel"
echo "" | base64 -d > "app/(main)/billing/cancel/invoice-modification-tab.js"
echo "Wrote app/(main)/billing/cancel/invoice-modification-tab.js"

git add "app/(main)/billing/cancel/invoice-modification-tab.js"
git commit -m "Lock original invoice line items in Invoice Modification; only new items removable"
git push

echo "Done."
